class MerkleMultiProof:
    """Multi-inclusion proof for ``indices`` within ``leaf_count`` leaves.

    ``siblings`` lists the digests the verifier cannot recompute, ordered
    level by level from leaf to root and left to right within each level.
    """

    leaf_count: int
    indices: tuple[int, ...]
    siblings: tuple[bytes, ...]


def _checked_multi_indices(indices: Sequence[int], size: int) -> list[int]:
    if isinstance(indices, (bytes, bytearray, str)) or not isinstance(indices, Sequence):
        raise TypeError("indices must be a sequence of integers")
    items = list(indices)  # copy: inputs are never mutated
    if not items:
        raise ValueError("indices must not be empty")
    previous: int | None = None
    for position, index in enumerate(items):
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError(f"indices[{position}] must be an integer")
        if previous is not None and index <= previous:
            raise ValueError("indices must be strictly increasing without duplicates")
        previous = index
    for index in items:
        if not 0 <= index < size:
            raise IndexError(f"index {index} out of range for {size} leaves")
    return items

def bound_wide_range_leaf(entry: WideRangeBatchEntry) -> bytes:
    items = [b"zkregion/wrb/v1"]
    commitment = entry.commitment
    items += [
        str(value).encode("ascii")
        for value in (
            commitment.element,
            commitment.lower,
            commitment.upper,
            commitment.prime,
            commitment.generator,
            commitment.h,
        )
    ]
    items.append(entry.context)
    items.append(str(len(entry.proof.commitments)).encode("ascii"))
    items += [str(value).encode("ascii") for value in entry.proof.commitments]
    for pairs in (entry.proof.challenges, entry.proof.responses):
        items.append(str(len(pairs)).encode("ascii"))
        items += [
            str(value).encode("ascii")
            for pair in pairs
            for value in pair
        ]
    return b"".join(len(item).to_bytes(4, "big") + item for item in items)


def bound_region_leaf(entry: RegionBatchEntry) -> bytes:
    items = [b"zkregion/region-bound/v1"]
    for commitment in (entry.x_commitment, entry.y_commitment):
        items += [
            str(value).encode("ascii")
            for value in (
                commitment.element,
                commitment.lower,
                commitment.upper,
                commitment.prime,
                commitment.generator,
                commitment.h,
            )
        ]
    region = entry.region
    items += [
        str(value).encode("ascii")
        for value in (region.min_x, region.max_x, region.min_y, region.max_y)
    ]
    items.append(entry.context)
    for sub_proof in (entry.proof.x_proof, entry.proof.y_proof):
        for sequence in (sub_proof.t, sub_proof.e, sub_proof.s):
            items.append(str(len(sequence)).encode("ascii"))
            items += [str(value).encode("ascii") for value in sequence]
    return b"".join(len(item).to_bytes(4, "big") + item for item in items)


